// VGM 1.71 DAC stream control tests.
//
// Every valid scenario is built twice:
//   * a "stream" VGM using 0x67 data blocks and the 0x90-0x95 commands;
//   * an "expanded" VGM generated by an independent reference model that
//     computes event ticks (integer phase accumulator) and bank byte values
//     itself, then emits plain 0x52 register-0x2A writes and waits.
// Both files are rendered through the real audio chain and compared sample
// for sample. The reference never calls the stream controller and never
// derives anything from emulator output.

#include "gme/gme.h"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <algorithm>
#include <limits>

namespace {

typedef std::vector<unsigned char> Bytes;

void put8( Bytes& v, unsigned x )        { v.push_back( (unsigned char) x ); }
void put16( Bytes& v, unsigned x )       { v.push_back( x & 255 ); v.push_back( (x >> 8) & 255 ); }
void put32( Bytes& v, uint32_t x )
{
	for ( int i = 0; i < 4; ++i ) v.push_back( (x >> (8 * i)) & 255 );
}
void put32at( Bytes& v, unsigned at, uint32_t x )
{
	for ( int i = 0; i < 4; ++i ) v [at + i] = (x >> (8 * i)) & 255;
}

Bytes vgm_header()
{
	Bytes v( 0x40, 0 );
	std::memcpy( v.data(), "Vgm ", 4 );
	put32at( v, 8, 0x160 );          // version 1.60
	put32at( v, 0x2C, 7670454 );     // YM2612 clock
	put32at( v, 0x34, 0x0C );        // data offset
	return v;
}

void reg_write( Bytes& v, unsigned reg, unsigned val )
{
	put8( v, 0x52 ); put8( v, reg ); put8( v, val );
}

// Waits are encoded with 0x61 (16-bit delay), split to stay in range.
void wait_ticks( Bytes& v, unsigned ticks )
{
	while ( ticks )
	{
		unsigned w = std::min( ticks, 65535u );
		put8( v, 0x61 ); put16( v, w );
		ticks -= w;
	}
}

void data_block( Bytes& v, Bytes const& p )
{
	put8( v, 0x67 ); put8( v, 0x66 ); put8( v, 0x00 );
	put32( v, (uint32_t) p.size() );
	v.insert( v.end(), p.begin(), p.end() );
}

void finish( Bytes& v, unsigned total_ticks, int loop_file_index = -1 )
{
	put8( v, 0x66 );
	put32at( v, 4, (uint32_t) v.size() - 4 );
	put32at( v, 0x18, total_ticks );
	if ( loop_file_index >= 0 )
	{
		// loop_offset is relative to the header field at 0x1C
		put32at( v, 0x1C, (uint32_t) (loop_file_index - 0x1C) );
		put32at( v, 0x20, total_ticks );
	}
}

// Stream command encoders (little-endian integers).
void s_setup( Bytes& v, unsigned id, unsigned chip, unsigned target, unsigned reg )
{
	put8( v, 0x90 ); put8( v, id ); put8( v, chip ); put8( v, target ); put8( v, reg );
}
void s_data( Bytes& v, unsigned id, unsigned bank, unsigned step, unsigned base )
{
	put8( v, 0x91 ); put8( v, id ); put8( v, bank ); put8( v, step ); put8( v, base );
}
void s_freq( Bytes& v, unsigned id, uint32_t f )
{
	put8( v, 0x92 ); put8( v, id ); put32( v, f );
}
void s_start( Bytes& v, unsigned id, uint32_t off, unsigned mode, uint32_t length, bool loop )
{
	put8( v, 0x93 ); put8( v, id ); put32( v, off );
	put8( v, mode | (loop ? 0x80u : 0u) ); put32( v, length );
}
void s_stop( Bytes& v, unsigned id ) { put8( v, 0x94 ); put8( v, id ); }
void s_fast( Bytes& v, unsigned id, unsigned block, bool loop )
{
	put8( v, 0x95 ); put8( v, id ); put8( v, block ); put8( v, loop ? 1 : 0 );
}
void pcm_seek( Bytes& v, uint32_t off ) { put8( v, 0xE0 ); put32( v, off ); }

// ---------------------------------------------------------------------------
// Independent reference model
// ---------------------------------------------------------------------------

struct Event { int tick; int value; };

struct Reference {
	Bytes bank;
	struct Stream {
		bool cfg = false;
		bool active = false;
		bool loop = false;
		uint32_t phase = 0;
		uint32_t freq = 0;
		uint32_t left = 0;
		uint32_t total = 0;
		long start = 0;
		long cur = 0;
		int step = 1;
		int base = 0;
	};
	Stream st [255];
	long legacy = 0;
	std::vector<Event> events;

	explicit Reference( std::vector<Bytes> const& blocks )
	{
		for ( Bytes const& b : blocks )
			bank.insert( bank.end(), b.begin(), b.end() );
	}

	void emit_at( int tick, long pos )
	{
		if ( pos < 0 || pos >= (long) bank.size() )
		{
			std::fprintf( stderr, "reference: bank position %ld out of range\n", pos );
			std::exit( 3 );
		}
		events.push_back( Event { tick, bank [(size_t) pos] } );
	}

	// Advance every active stream over ticks (now, to].
	void pump( int now, int to )
	{
		for ( int t = now + 1; t <= to; ++t )
		{
			for ( int id = 0; id < 255; ++id )
			{
				Stream& s = st [id];
				if ( !s.active ) continue;
				s.phase += s.freq;
				if ( s.phase < 44100u ) continue;
				s.phase -= 44100u;
				emit_at( t, s.cur );
				--s.left;
				if ( s.left == 0 )
				{
					if ( s.loop ) { s.cur = s.start; s.left = s.total; }
					else s.active = false;
				}
				else
					s.cur += s.step;
			}
		}
	}

	void begin( Stream& s, int id, long pos, uint32_t total, bool loop, int tick )
	{
		if ( total == 0 )
		{
			// Zero writes: a valid range that makes no sound at all.
			s.active = false;
			return;
		}
		s.active = true;
		s.loop = loop;
		s.phase = 0;
		s.start = s.cur = pos;
		s.total = s.left = total;
		emit_at( tick, pos );
		--s.left;
		if ( s.left == 0 )
		{
			if ( s.loop ) { s.cur = s.start; s.left = s.total; }
			else s.active = false;
		}
		else
			s.cur += s.step;
		(void) id;
	}

	void setup( int id ) { st [id] = Stream(); st [id].cfg = true; }
	void set_data( int id, int step, int base )
	{
		Stream& s = st [id]; s.active = false; s.step = step; s.base = base;
	}
	void set_freq( int id, uint32_t f ) { st [id].freq = f; }
	void start( int id, uint32_t off, uint32_t length, bool loop, int tick )
	{
		Stream& s = st [id];
		s.active = false;
		begin( s, id, (long) off + s.base, length, loop, tick );
	}
	void fast( int id, int block, std::vector<Bytes> const& blocks,
			std::vector<long> const& starts, bool loop, int tick )
	{
		Stream& s = st [id];
		long remain = (long) blocks [block].size() - s.base;
		uint32_t total = (uint32_t) ((remain + s.step - 1) / s.step);
		begin( s, id, starts [block] + s.base, total, loop, tick );
	}
	void stop( int id )
	{
		if ( id == 255 )
			for ( auto& x : st ) x.active = false;
		else
			st [id].active = false;
	}
	void legacy_seek( long off ) { legacy = off; }
	void legacy_read( int tick )
	{
		emit_at( tick, legacy );
		++legacy;
	}
};

// Build the expanded all-explicit-writes VGM from reference events.
Bytes expanded_vgm( std::vector<Event> const& events, unsigned total_ticks )
{
	Bytes v = vgm_header();
	reg_write( v, 0x2B, 0x80 ); // DAC enable at tick 0
	int now = 0;
	for ( Event const& e : events )
	{
		wait_ticks( v, (unsigned) (e.tick - now) );
		reg_write( v, 0x2A, (unsigned) e.value );
		now = e.tick;
	}
	wait_ticks( v, total_ticks - now );
	finish( v, total_ticks );
	return v;
}

// ---------------------------------------------------------------------------
// Rendering and comparison
// ---------------------------------------------------------------------------

void gme_check( gme_err_t err, const char* what )
{
	if ( err )
	{
		std::fprintf( stderr, "gme error at %s: %s\n", what, err );
		std::exit( 3 );
	}
}

std::vector<short> render( Bytes const& vgm, int rate, long samples,
		const int* sizes, int nsizes, double tempo, std::string* warning )
{
	Music_Emu* e = gme_new_emu( gme_vgm_type, rate );
	if ( !e ) std::exit( 3 );
	gme_check( gme_load_data( e, vgm.data(), (long) vgm.size() ), "load" );
	gme_ignore_silence( e, 1 );
	gme_set_autoload_playback_limit( e, 0 );
	if ( tempo != 1.0 ) gme_set_tempo( e, tempo );
	gme_check( gme_start_track( e, 0 ), "start" );

	std::vector<short> out( samples );
	long done = 0;
	int k = 0;
	while ( done < samples )
	{
		long n = sizes ? sizes [k++ % nsizes] : samples;
		if ( n > samples - done ) n = samples - done;
		gme_check( gme_play( e, (int) n, out.data() + done ), "play" );
		done += n;
	}
	const char* w = gme_warning( e );
	if ( warning ) *warning = w ? w : "";
	gme_delete( e );
	return out;
}

int failures = 0;

bool compare_pcm( const char* name, std::vector<short> const& want,
		std::vector<short> const& got, const char* tag )
{
	if ( want.size() != got.size() )
	{
		std::fprintf( stderr, "%s [%s]: length mismatch want=%zu got=%zu\n",
				name, tag, want.size(), got.size() );
		++failures;
		return false;
	}
	for ( size_t i = 0; i < want.size(); ++i )
	{
		if ( want [i] != got [i] )
		{
			std::fprintf( stderr,
					"%s [%s]: first mismatch at sample %zu want=%d got=%d\n",
					name, tag, i, (int) want [i], (int) got [i] );
			++failures;
			return false;
		}
	}
	return true;
}

// Full matrix: same abstract scenario rendered several ways, each time the
// stream file must equal its independently expanded twin sample for sample.
// Render lengths are derived from the VGM timeline so no configuration runs
// past total_ticks, where a looped stream file and an ended expanded file
// legitimately diverge; a fixed headroom covers one internal render frame.
void check_scenario( const char* name, Bytes const& stream_file,
		std::vector<Event> const& events, unsigned total_ticks,
		bool check_no_warning = true )
{
	Bytes expanded = expanded_vgm( events, total_ticks );
	static const int chopped [] = { 2, 14, 514, 6, 1028, 126 }; // 1/7/257 stereo frames etc.
	const long vgm_headroom = 2000; // >= one ~33 ms internal frame in ticks

	struct Cfg { int rate; const int* sizes; int n; double tempo; const char* tag; };
	Cfg cfgs [] = {
		{ 44100, 0,       0, 1.0, "44100-whole" },
		{ 44100, chopped, 6, 1.0, "44100-chunk" },
		{ 48000, 0,       0, 1.0, "48000-whole" },
		{ 48000, chopped, 6, 1.0, "48000-chunk" },
		{ 44100, chopped, 6, 0.5, "44100-tempo-half" },
		{ 44100, chopped, 6, 1.5, "44100-tempo-1.5" },
	};
	for ( Cfg const& c : cfgs )
	{
		// vgm ticks consumed per output frame = 44100 * tempo / rate.
		long frames = (long) ((total_ticks - vgm_headroom) * c.rate /
				(44100.0 * c.tempo));
		long samples = frames * 2; // stereo
		std::string we, ge;
		std::vector<short> want = render( expanded, c.rate, samples, c.sizes, c.n, c.tempo, &we );
		std::vector<short> got  = render( stream_file, c.rate, samples, c.sizes, c.n, c.tempo, &ge );
		compare_pcm( name, want, got, c.tag );
		if ( check_no_warning && !ge.empty() )
		{
			std::fprintf( stderr, "%s [%s]: unexpected warning: %s\n", name, c.tag, ge.c_str() );
			++failures;
		}
	}
}

// ---------------------------------------------------------------------------
// Scenario descriptions
// ---------------------------------------------------------------------------

enum OpKind {
	OP_BLOCK, OP_SETUP, OP_DATA, OP_FREQ, OP_START, OP_FAST, OP_STOP,
	OP_LEGACY_SEEK, OP_LEGACY_READ
};
struct Op {
	OpKind kind;
	int tick;
	int id, a, b, c;
	uint32_t u, v;
	bool loop;
	Op( OpKind k, int t, int i = 0, int aa = 0, int bb = 0, int cc = 0,
			uint32_t uu = 0, uint32_t vv = 0, bool l = false )
		: kind( k ), tick( t ), id( i ), a( aa ), b( bb ), c( cc ),
		  u( uu ), v( vv ), loop( l ) { }

	// Named constructors keep argument meaning explicit at every call site.
	static Op block( int t, int idx ) { return Op( OP_BLOCK, t, idx ); }
	static Op setup( int t, int idx ) { return Op( OP_SETUP, t, idx ); }
	static Op data( int t, int idx, int bank, int step, int base )
		{ return Op( OP_DATA, t, idx, bank, step, base ); }
	static Op freq( int t, int idx, uint32_t hz )
		{ return Op( OP_FREQ, t, idx, 0, 0, 0, hz ); }
	static Op start( int t, int idx, uint32_t off, int mode, uint32_t len, bool lp )
		{ return Op( OP_START, t, idx, mode, 0, 0, off, len, lp ); }
	static Op fast( int t, int idx, int blk, bool lp )
		{ return Op( OP_FAST, t, idx, blk, 0, 0, 0, 0, lp ); }
	static Op stop( int t, int idx ) { return Op( OP_STOP, t, idx ); }
	static Op legacy_seek( int t, uint32_t off )
		{ return Op( OP_LEGACY_SEEK, t, 0, 0, 0, 0, off ); }
	static Op legacy_read( int t, int n )
		{ return Op( OP_LEGACY_READ, t, 0, n ); }
};

// Concatenated block start offsets within the bank.
std::vector<long> block_starts( std::vector<Bytes> const& blocks )
{
	std::vector<long> starts;
	long at = 0;
	for ( Bytes const& b : blocks ) { starts.push_back( at ); at += (long) b.size(); }
	return starts;
}

// Build the stream-controlled VGM for an op list and, in parallel, run the
// independent reference to obtain its expected event timeline.
void build_pair( std::vector<Bytes> const& blocks, std::vector<Op> const& ops,
		unsigned total_ticks, Bytes& stream_file, Reference*& ref_out )
{
	Reference* ref = new Reference( blocks );
	Bytes v = vgm_header();
	reg_write( v, 0x2B, 0x80 );
	int now = 0;
	for ( Op const& op : ops )
	{
		ref->pump( now, op.tick );
		wait_ticks( v, (unsigned) (op.tick - now) );
		now = op.tick;
		switch ( op.kind )
		{
		case OP_BLOCK:
			data_block( v, blocks [op.id] );
			break;
		case OP_SETUP:
			// Every scenario targets the supported YM2612 port-0 DAC reg;
			// unsupported chip/register setups are built directly in invalid.
			s_setup( v, op.id, 0, 0, 0x2A );
			ref->setup( op.id );
			break;
		case OP_DATA:
			s_data( v, op.id, op.a, op.b, op.c );
			ref->set_data( op.id, op.b, op.c );
			break;
		case OP_FREQ:
			s_freq( v, op.id, op.u );
			ref->set_freq( op.id, op.u );
			break;
		case OP_START:
			s_start( v, op.id, op.u, op.a, op.v, op.loop );
			ref->start( op.id, op.u, op.v, op.loop, op.tick );
			break;
		case OP_FAST:
			s_fast( v, op.id, op.a, op.loop );
			ref->fast( op.id, op.a, blocks, block_starts( blocks ), op.loop, op.tick );
			break;
		case OP_STOP:
			s_stop( v, op.id );
			ref->stop( op.id );
			break;
		case OP_LEGACY_SEEK:
			pcm_seek( v, op.u );
			ref->legacy_seek( (long) op.u );
			break;
		case OP_LEGACY_READ:
			put8( v, 0x80 | (op.a & 0x0F) );
			ref->legacy_read( op.tick );
			now += op.a; // 0x8n advances n ticks after the read
			break;
		}
	}
	ref->pump( now, (int) total_ticks );
	wait_ticks( v, total_ticks - now );
	finish( v, total_ticks );
	stream_file.swap( v );
	ref_out = ref;
}

Bytes make_block( unsigned seed, unsigned n )
{
	Bytes b;
	for ( unsigned i = 0; i < n; ++i ) b.push_back( (unsigned char) ((seed * 37 + i * 13 + 7) & 0xFF) );
	return b;
}

const unsigned TOTAL_TICKS = 20000;
// Stereo samples spanning the full TOTAL_TICKS timeline at 44100 (used by the
// deterministic same-file and legacy comparisons that stay inside the timeline).
const long SAMPLES_44 = 40000;

// ---- 1. bank_blocks -------------------------------------------------------
void case_bank_blocks()
{
	const char* name = "bank_blocks";
	Bytes b0 = make_block( 3, 8 );    // bank positions 0..7
	Bytes b1 = make_block( 9, 8 );    // bank positions 8..15
	std::vector<Bytes> blocks; blocks.push_back( b0 ); blocks.push_back( b1 );

	std::vector<Op> ops;
	// Second block appears mid-stream, before any read reaches it.
	ops.push_back( Op::block( 0, 0 ) );
	ops.push_back( Op::setup( 10, 0 ) );
	ops.push_back( Op::data( 20, 0, 0, 2, 1 ) ); // bank 0, step 2, base 1
	ops.push_back( Op::freq( 30, 0, 11025 ) );
	// Cross-block count mode: start 5, step 2, six writes -> 5,7,9,11,13,15.
	// The third value (position 9) is due at tick 48, so block 1 is made
	// available at tick 45: after the start but before that cross-block read.
	ops.push_back( Op::start( 40, 0, 4, 1, 6, false ) );
	ops.push_back( Op::block( 45, 1 ) );

	// Fast start limited to block 1, step 1, base 0: positions 8..15.
	ops.push_back( Op::setup( 400, 1 ) );
	ops.push_back( Op::data( 410, 1, 0, 1, 0 ) );
	ops.push_back( Op::freq( 420, 1, 22050 ) );
	ops.push_back( Op::fast( 430, 1, 1, false ) );

	// Legacy cursor: seek to 6, read five consecutive bytes (6..10), which
	// crosses the block boundary one byte at a time with its own cursor.
	ops.push_back( Op::legacy_seek( 900, 6 ) );
	for ( int i = 0; i < 5; ++i )
		ops.push_back( Op::legacy_read( 910 + i * 5, 3 ) );

	Bytes stream_file; Reference* ref;
	build_pair( blocks, ops, TOTAL_TICKS, stream_file, ref );
	check_scenario( name, stream_file, ref->events, TOTAL_TICKS );
	delete ref;

	// A zero-write start is valid but emits nothing, and 0x94 with stream ID
	// 0xFF stops every running stream at once.
	std::vector<Op> ops2;
	ops2.push_back( Op::block( 0, 0 ) );
	ops2.push_back( Op::setup( 10, 0 ) );
	ops2.push_back( Op::data( 10, 0, 0, 1, 0 ) );
	ops2.push_back( Op::freq( 10, 0, 11025 ) );
	ops2.push_back( Op::start( 20, 0, 0, 1, 0, false ) ); // zero writes: silent
	ops2.push_back( Op::setup( 30, 2 ) );
	ops2.push_back( Op::data( 30, 2, 0, 1, 0 ) );
	ops2.push_back( Op::freq( 30, 2, 8000 ) );
	// Looping over the 8-byte block so the stream is definitely still active
	// when the stop-all arrives.
	ops2.push_back( Op::start( 40, 2, 0, 1, 8, true ) );
	ops2.push_back( Op::stop( 500, 255 ) );               // stop all streams
	Bytes sf2; Reference* ref2;
	build_pair( blocks, ops2, TOTAL_TICKS, sf2, ref2 );
	check_scenario( name, sf2, ref2->events, TOTAL_TICKS );
	// The stop-all must leave no event at or after the stop tick.
	if ( !ref2->events.empty() && ref2->events.back().tick >= 500 )
	{
		std::fprintf( stderr, "%s [stop-all]: event after stop at tick %d\n",
				name, ref2->events.back().tick );
		++failures;
	}
	delete ref2;

	// Looping 0x95 fast start: step 2, base 1 on block 1 (bank positions
	// 8..15). Every value, including after wraps, must stay inside block 1 and
	// never borrow a byte from a neighboring block.
	std::vector<Op> ops3;
	ops3.push_back( Op::block( 0, 0 ) );
	ops3.push_back( Op::block( 1, 1 ) );
	ops3.push_back( Op::setup( 10, 4 ) );
	ops3.push_back( Op::data( 10, 4, 0, 2, 1 ) ); // step 2, base 1
	ops3.push_back( Op::freq( 10, 4, 11025 ) );
	ops3.push_back( Op::fast( 20, 4, 1, true ) ); // block 1, looping
	Bytes sf3; Reference* ref3;
	build_pair( blocks, ops3, TOTAL_TICKS, sf3, ref3 );
	check_scenario( name, sf3, ref3->events, TOTAL_TICKS );
	// Block 1 occupies bank positions [8,16). base 1 + k*step gives 9,11,13,15.
	for ( Event const& e : ref3->events )
	{
		// Recover the bank position by matching the emitted value uniquely is
		// unnecessary: the reference fast() already bounds total to the block,
		// so assert the values are exactly the expected step/base sequence.
		static const unsigned char want_vals [] = {
			b1 [1], b1 [3], b1 [5], b1 [7] };
		unsigned char wv = want_vals [((e.tick - 20) / 4) % 4];
		if ( (unsigned char) e.value != wv )
		{
			std::fprintf( stderr,
					"%s [looping-fast]: tick %d value %d outside block-1 sequence\n",
					name, e.tick, e.value );
			++failures;
			break;
		}
	}
	delete ref3;
}

// ---- 2. rational_waits ----------------------------------------------------
void case_rational_waits()
{
	const char* name = "rational_waits";
	Bytes b0 = make_block( 5, 240 );
	std::vector<Bytes> blocks; blocks.push_back( b0 );

	std::vector<Op> ops;
	ops.push_back( Op::block( 0, 0 ) );
	ops.push_back( Op::setup( 0, 0 ) );
	ops.push_back( Op::data( 0, 0, 0, 1, 0 ) );
	// 16000 Hz does not divide 44100: period 2.75625 ticks.
	ops.push_back( Op::freq( 0, 0, 16000 ) );
	ops.push_back( Op::start( 100, 0, 0, 1, 200, false ) );

	Bytes stream_file; Reference* ref;
	build_pair( blocks, ops, TOTAL_TICKS, stream_file, ref );
	// The matrix already covers both output rates, chunked reads and tempo,
	// and the 16 kHz stream spans many internal render frames.
	check_scenario( name, stream_file, ref->events, TOTAL_TICKS );
	delete ref;
}

// ---- 3. controls ----------------------------------------------------------
void case_controls()
{
	const char* name = "controls";
	Bytes b0 = make_block( 7, 200 );
	std::vector<Bytes> blocks; blocks.push_back( b0 );
	std::vector<Op> ops;
	ops.push_back( Op::block( 0, 0 ) );

	// All configuration happens at tick 10 (monotonic op timeline).
	// Two looping streams with the same frequency, started together at tick
	// 20, so every recurring write is due simultaneously and ascending stream
	// ID decides the DAC order. They read different bank regions.
	ops.push_back( Op::setup( 10, 3 ) );
	ops.push_back( Op::data( 10, 3, 0, 1, 0 ) );
	ops.push_back( Op::freq( 10, 3, 11025 ) );
	ops.push_back( Op::setup( 10, 7 ) );
	ops.push_back( Op::data( 10, 7, 0, 1, 0 ) );
	ops.push_back( Op::freq( 10, 7, 11025 ) );

	ops.push_back( Op::start( 20, 3, 0, 1, 40, true ) );
	ops.push_back( Op::start( 20, 7, 60, 1, 40, true ) );

	// Frequency change keeps position and phase; no extra first value.
	ops.push_back( Op::freq( 2000, 3, 22050 ) );

	// Stop stream 3; stream 7 keeps running on its own phase.
	ops.push_back( Op::stop( 4000, 3 ) );

	// Restart stream 3: fresh first value immediately, phase cleared.
	ops.push_back( Op::freq( 4010, 3, 8000 ) );
	ops.push_back( Op::start( 4020, 3, 10, 1, 40, true ) );

	// Replace stream 7's range outright (new start, cleared phase).
	ops.push_back( Op::start( 8000, 7, 120, 1, 30, true ) );

	Bytes stream_file; Reference* ref;
	build_pair( blocks, ops, TOTAL_TICKS, stream_file, ref );
	check_scenario( name, stream_file, ref->events, TOTAL_TICKS );
	delete ref;
}

// ---- 4. loop_restart ------------------------------------------------------
void case_loop_restart()
{
	const char* name = "loop_restart";
	Bytes b0 = make_block( 11, 64 );
	const unsigned loop_ticks = 2500;   // file loop period

	// Independent reference: one looping stream started at tick 100 and left
	// running across several file loops. The file loop only moves the command
	// pointer; the stream's own phase is untouched, so the reference timeline
	// is continuous with no re-begin.
	Reference ref( std::vector<Bytes> { b0 } );
	ref.st [2].cfg = true;
	ref.st [2].step = 1; ref.st [2].base = 0; ref.st [2].freq = 12000;
	ref.begin( ref.st [2], 2, 0, 64, true, 100 );
	ref.pump( 100, (int) TOTAL_TICKS );

	// Stream file. Block 0 is registered once, before the loop region, and a
	// second type-0 block is placed *inside* the loop region so the same
	// physical 0x67 command is re-parsed on every jump: a correct
	// implementation dedupes it by address (stable block numbering, no bank
	// growth), while a naive append would proliferate blocks. The looping
	// stream is configured and started before the loop region and is never
	// re-issued, so it crosses every file loop on its own phase.
	Bytes v = vgm_header();
	reg_write( v, 0x2B, 0x80 );
	data_block( v, b0 );
	s_setup( v, 2, 0, 0, 0x2A );
	s_data( v, 2, 0, 1, 0 );
	s_freq( v, 2, 12000 );
	wait_ticks( v, 100 );                 // start lands on tick 100 like the reference
	s_start( v, 2, 0, 1, 64, true );
	unsigned loop_target = (unsigned) v.size();
	{
		Bytes b1 = make_block( 13, 16 );
		data_block( v, b1 );      // re-parsed on every loop, deduped by address
	}
	wait_ticks( v, loop_ticks );
	finish( v, TOTAL_TICKS, (int) loop_target );

	check_scenario( name, v, ref.events, TOTAL_TICKS );

	// Restart: a second start_track must reproduce the first render exactly.
	{
		static const int chopped [] = { 2, 14, 514 };
		std::string w;
		std::vector<short> first = render( v, 44100, SAMPLES_44, chopped, 3, 1.0, &w );
		Music_Emu* e = gme_new_emu( gme_vgm_type, 44100 );
		gme_check( gme_load_data( e, v.data(), (long) v.size() ), "load" );
		gme_ignore_silence( e, 1 );
		gme_set_autoload_playback_limit( e, 0 );
		gme_check( gme_start_track( e, 0 ), "start" );
		std::vector<short> again( SAMPLES_44 );
		long done = 0; int k = 0;
		while ( done < SAMPLES_44 )
		{
			long n = chopped [k++ % 3];
			if ( n > SAMPLES_44 - done ) n = SAMPLES_44 - done;
			gme_check( gme_play( e, (int) n, again.data() + done ), "play" );
			done += n;
		}
		compare_pcm( name, first, again, "restart" );
		gme_delete( e );
	}

	// Backward seek must drop stream state and reproduce the opening segment.
	{
		Music_Emu* e = gme_new_emu( gme_vgm_type, 44100 );
		gme_check( gme_load_data( e, v.data(), (long) v.size() ), "load" );
		gme_ignore_silence( e, 1 );
		gme_set_autoload_playback_limit( e, 0 );
		gme_check( gme_start_track( e, 0 ), "start" );
		std::vector<short> scratch( 4000 );
		gme_check( gme_play( e, (int) scratch.size(), scratch.data() ), "play" );
		gme_check( gme_seek( e, 0 ), "seek" );
		std::vector<short> after( 4000 );
		gme_check( gme_play( e, (int) after.size(), after.data() ), "play" );
		std::string w;
		std::vector<short> fresh = render( v, 44100, 4000, 0, 0, 1.0, &w );
		compare_pcm( name, fresh, after, "backward-seek" );
		gme_delete( e );
	}

	// Loading a different file into the same emulator must leave no state.
	{
		Bytes other_b = make_block( 21, 50 );
		std::vector<Bytes> ob; ob.push_back( other_b );
		std::vector<Op> oops;
		oops.push_back( Op::block( 0, 0 ) );
		oops.push_back( Op::setup( 0, 0 ) );
		oops.push_back( Op::data( 0, 0, 0, 1, 0 ) );
		oops.push_back( Op::freq( 0, 0, 20000 ) );
		oops.push_back( Op::start( 0, 0, 0, 1, 40, false ) );
		Bytes other_stream; Reference* other_ref;
		build_pair( ob, oops, TOTAL_TICKS, other_stream, other_ref );
		Bytes other_exp = expanded_vgm( other_ref->events, TOTAL_TICKS );

		Music_Emu* e = gme_new_emu( gme_vgm_type, 44100 );
		gme_check( gme_load_data( e, v.data(), (long) v.size() ), "load1" );
		gme_check( gme_start_track( e, 0 ), "start1" );
		std::vector<short> junk( 2000 );
		gme_check( gme_play( e, (int) junk.size(), junk.data() ), "play1" );
		gme_check( gme_load_data( e, other_stream.data(), (long) other_stream.size() ), "load2" );
		gme_ignore_silence( e, 1 );
		gme_set_autoload_playback_limit( e, 0 );
		gme_check( gme_start_track( e, 0 ), "start2" );
		std::vector<short> got( 8000 );
		gme_check( gme_play( e, (int) got.size(), got.data() ), "play2" );
		std::string w;
		std::vector<short> want = render( other_exp, 44100, 8000, 0, 0, 1.0, &w );
		compare_pcm( name, want, got, "reload" );
		gme_delete( e );
		delete other_ref;
	}
}

// ---- 5. invalid -----------------------------------------------------------
void expect_warning( const char* name, const char* tag, Bytes v,
		bool must_end, bool expect_sound_from_neighbor = false )
{
	Music_Emu* e = gme_new_emu( gme_vgm_type, 44100 );
	if ( !e ) std::exit( 3 );
	gme_err_t err = gme_load_data( e, v.data(), (long) v.size() );
	if ( err ) { std::fprintf( stderr, "%s [%s]: load rejected: %s\n", name, tag, err ); ++failures; gme_delete( e ); return; }
	gme_ignore_silence( e, 1 );
	gme_set_autoload_playback_limit( e, 0 );
	err = gme_start_track( e, 0 );
	if ( err ) { std::fprintf( stderr, "%s [%s]: start rejected: %s\n", name, tag, err ); ++failures; gme_delete( e ); return; }
	std::vector<short> out( 8000, 0 );
	gme_check( gme_play( e, (int) out.size(), out.data() ), "play" );
	const char* w = gme_warning( e );
	if ( !w )
	{
		std::fprintf( stderr, "%s [%s]: expected warning, got none\n", name, tag );
		++failures;
	}
	if ( must_end && !gme_track_ended( e ) )
	{
		std::fprintf( stderr, "%s [%s]: expected controlled track end\n", name, tag );
		++failures;
	}
	long nz = 0;
	for ( short s : out ) nz += s != 0;
	if ( expect_sound_from_neighbor && nz == 0 )
	{
		std::fprintf( stderr, "%s [%s]: valid neighbor stream produced no sound\n", name, tag );
		++failures;
	}
	if ( !expect_sound_from_neighbor && nz != 0 && must_end )
	{
		// Truncated files should end quietly rather than emit garbage.
		std::fprintf( stderr, "%s [%s]: truncated input emitted %ld samples\n", name, tag, nz );
		++failures;
	}
	gme_delete( e );
}

Bytes minimal_header()
{
	Bytes v = vgm_header();
	reg_write( v, 0x2B, 0x80 );
	return v;
}

void case_invalid()
{
	const char* name = "invalid";
	Bytes b0 = make_block( 4, 64 );

	{ // truncated 0x90: parameters run into EOF
		Bytes v = minimal_header();
		put8( v, 0x90 ); put8( v, 0 ); put8( v, 0 );
		finish( v, 5000 );
		expect_warning( name, "truncated-0x90", v, true );
	}
	{ // truncated 0x93: only half the offset, bytes after must not become commands
		Bytes v = minimal_header();
		data_block( v, b0 );
		s_setup( v, 0, 0, 0, 0x2A );
		s_data( v, 0, 0, 1, 0 );
		s_freq( v, 0, 11025 );
		put8( v, 0x93 ); put8( v, 0 ); put8( v, 0 ); put8( v, 5 );
		finish( v, 5000 );
		expect_warning( name, "truncated-0x93", v, true );
	}
	{ // 0x67 size extends past EOF
		Bytes v = minimal_header();
		put8( v, 0x67 ); put8( v, 0x66 ); put8( v, 0 ); put32( v, 1000 );
		put8( v, 1 ); put8( v, 2 );
		finish( v, 5000 );
		expect_warning( name, "block-past-eof", v, true );
	}
	{ // start before setup
		Bytes v = minimal_header();
		data_block( v, b0 );
		s_start( v, 4, 0, 1, 10, false );
		wait_ticks( v, 3000 );
		finish( v, 5000 );
		expect_warning( name, "unconfigured-start", v, false );
	}
	{ // invalid block number in fast start
		Bytes v = minimal_header();
		data_block( v, b0 );
		s_setup( v, 0, 0, 0, 0x2A );
		s_data( v, 0, 0, 1, 0 );
		s_freq( v, 0, 11025 );
		s_fast( v, 0, 7, false );
		wait_ticks( v, 3000 );
		finish( v, 5000 );
		expect_warning( name, "bad-block", v, false );
	}
	{ // out of range offset in 0x93
		Bytes v = minimal_header();
		data_block( v, b0 );
		s_setup( v, 0, 0, 0, 0x2A );
		s_data( v, 0, 0, 1, 0 );
		s_freq( v, 0, 11025 );
		s_start( v, 0, 1000, 1, 10, false );
		wait_ticks( v, 3000 );
		finish( v, 5000 );
		expect_warning( name, "bad-offset", v, false );
	}
	{ // step 0 and base >= step in two files
		Bytes v1 = minimal_header(); data_block( v1, b0 );
		s_setup( v1, 0, 0, 0, 0x2A ); s_data( v1, 0, 0, 0, 0 );
		s_freq( v1, 0, 11025 ); s_start( v1, 0, 0, 1, 5, false );
		wait_ticks( v1, 3000 ); finish( v1, 5000 );
		expect_warning( name, "step-zero", v1, false );

		Bytes v2 = minimal_header(); data_block( v2, b0 );
		s_setup( v2, 0, 0, 0, 0x2A ); s_data( v2, 0, 0, 2, 2 );
		s_freq( v2, 0, 11025 ); s_start( v2, 0, 0, 1, 5, false );
		wait_ticks( v2, 3000 ); finish( v2, 5000 );
		expect_warning( name, "base-not-less-step", v2, false );
	}
	{ // frequency zero and frequency above 44100
		Bytes v1 = minimal_header(); data_block( v1, b0 );
		s_setup( v1, 0, 0, 0, 0x2A ); s_data( v1, 0, 0, 1, 0 );
		s_freq( v1, 0, 0 ); s_start( v1, 0, 0, 1, 5, false );
		wait_ticks( v1, 3000 ); finish( v1, 5000 );
		expect_warning( name, "freq-zero", v1, false );

		Bytes v2 = minimal_header(); data_block( v2, b0 );
		s_setup( v2, 0, 0, 0, 0x2A ); s_data( v2, 0, 0, 1, 0 );
		s_freq( v2, 0, 44101 ); s_start( v2, 0, 0, 1, 5, false );
		wait_ticks( v2, 3000 ); finish( v2, 5000 );
		expect_warning( name, "freq-too-high", v2, false );
	}
	{ // unsupported length mode, 0xFFFFFFFF offset, wrong register, bank 1,
	  // and 0xFF used outside 0x94
		Bytes v1 = minimal_header(); data_block( v1, b0 );
		s_setup( v1, 0, 0, 0, 0x2A ); s_data( v1, 0, 0, 1, 0 ); s_freq( v1, 0, 11025 );
		s_start( v1, 0, 0, 0, 5, false ); // mode 0 unsupported
		wait_ticks( v1, 3000 ); finish( v1, 5000 );
		expect_warning( name, "bad-mode", v1, false );

		// Reverse (mode 2) and mode 3 length modes are out of scope: each must
		// be fully consumed, warn and stop the stream, never misparsed.
		for ( int bad_mode = 2; bad_mode <= 3; ++bad_mode )
		{
			Bytes vm = minimal_header(); data_block( vm, b0 );
			s_setup( vm, 0, 0, 0, 0x2A ); s_data( vm, 0, 0, 1, 0 ); s_freq( vm, 0, 11025 );
			s_start( vm, 0, 0, bad_mode, 5, false );
			// A following legal command must still parse correctly.
			wait_ticks( vm, 1000 );
			s_stop( vm, 0 );
			wait_ticks( vm, 2000 ); finish( vm, 5000 );
			expect_warning( name, bad_mode == 2 ? "reverse-mode" : "length-mode-3",
					vm, false );
		}

		Bytes v2 = minimal_header(); data_block( v2, b0 );
		s_setup( v2, 0, 0, 0, 0x2A ); s_data( v2, 0, 0, 1, 0 ); s_freq( v2, 0, 11025 );
		s_start( v2, 0, 0xFFFFFFFFu, 1, 5, false );
		wait_ticks( v2, 3000 ); finish( v2, 5000 );
		expect_warning( name, "offset-marker", v2, false );

		Bytes v3 = minimal_header(); data_block( v3, b0 );
		s_setup( v3, 0, 0, 0, 0x29 ); // not DAC register
		s_data( v3, 0, 0, 1, 0 ); s_freq( v3, 0, 11025 );
		s_start( v3, 0, 0, 1, 5, false );
		wait_ticks( v3, 3000 ); finish( v3, 5000 );
		expect_warning( name, "wrong-register", v3, false );

		Bytes v4 = minimal_header(); data_block( v4, b0 );
		s_setup( v4, 0, 0, 0, 0x2A ); s_data( v4, 0, 1, 1, 0 ); // bank 1
		s_freq( v4, 0, 11025 ); s_start( v4, 0, 0, 1, 5, false );
		wait_ticks( v4, 3000 ); finish( v4, 5000 );
		expect_warning( name, "bad-bank", v4, false );

		Bytes v5 = minimal_header(); data_block( v5, b0 );
		s_setup( v5, 0, 0, 0, 0x2A );
		s_freq( v5, 0xFF, 11025 ); // 0xFF ignored outside 0x94
		wait_ticks( v5, 3000 ); finish( v5, 5000 );
		expect_warning( name, "reserved-id", v5, false );
	}
	{ // a bad stream 1 must not silence a correctly running stream 0
		Bytes v = minimal_header(); data_block( v, b0 );
		s_setup( v, 0, 0, 0, 0x2A ); s_data( v, 0, 0, 1, 0 ); s_freq( v, 0, 11025 );
		s_start( v, 0, 0, 1, 40, false );
		s_fast( v, 1, 9, false ); // stream 1 was never configured
		wait_ticks( v, 6000 ); finish( v, 8000 );
		expect_warning( name, "neighbor-survives", v, false, true );
	}
}

// ---- 6. legacy ------------------------------------------------------------
void case_legacy()
{
	const char* name = "legacy";

	// Explicit direct DAC writes must be stable across read patterns.
	Bytes b0 = make_block( 2, 128 );
	Bytes direct = vgm_header();
	reg_write( direct, 0x2B, 0x80 );
	for ( unsigned i = 0; i < b0.size(); ++i )
	{
		reg_write( direct, 0x2A, b0 [i] );
		wait_ticks( direct, 4 );
	}
	wait_ticks( direct, 4000 );
	finish( direct, TOTAL_TICKS );
	static const int chopped [] = { 2, 14, 514, 6 };
	std::string w;
	std::vector<short> whole = render( direct, 44100, SAMPLES_44, 0, 0, 1.0, &w );
	std::vector<short> chunks = render( direct, 44100, SAMPLES_44, chopped, 4, 1.0, &w );
	compare_pcm( name, whole, chunks, "direct-dac-determinism" );
	long nz = 0; for ( short s : whole ) nz += s != 0;
	if ( nz == 0 ) { std::fprintf( stderr, "%s: direct DAC produced silence\n", name ); ++failures; }

	// Single-block 0xE0/0x8n playback must equal an explicit-write twin. Both
	// files span the whole timeline so the held DAC level is compared for the
	// entire render, not just until one of them reaches its end event.
	std::vector<Bytes> blocks; blocks.push_back( b0 );
	Reference ref( blocks );
	Bytes legacy = vgm_header();
	reg_write( legacy, 0x2B, 0x80 );
	data_block( legacy, b0 );
	pcm_seek( legacy, 10 );
	ref.legacy_seek( 10 );
	int now = 0;
	for ( int i = 0; i < 30; ++i )
	{
		ref.legacy_read( now );
		put8( legacy, 0x81 ); // one byte, then advance one tick
		now += 1;
	}
	wait_ticks( legacy, TOTAL_TICKS - (unsigned) now );
	finish( legacy, TOTAL_TICKS );
	Bytes twin = expanded_vgm( ref.events, TOTAL_TICKS );
	std::vector<short> want = render( twin, 44100, SAMPLES_44, chopped, 4, 1.0, &w );
	std::vector<short> got  = render( legacy, 44100, SAMPLES_44, chopped, 4, 1.0, &w );
	compare_pcm( name, want, got, "e0-8n-bank" );

	// An out-of-bank legacy seek warns instead of forming a wild pointer.
	Bytes bad = vgm_header();
	reg_write( bad, 0x2B, 0x80 );
	data_block( bad, b0 );
	pcm_seek( bad, 5000 );
	put8( bad, 0x81 );
	wait_ticks( bad, 3000 );
	finish( bad, TOTAL_TICKS );
	expect_warning( name, "legacy-oob", bad, false );
}

// ---------------------------------------------------------------------------

struct CaseDef { const char* name; void (*fn)(); };

} // namespace

int main( int argc, char** argv )
{
	CaseDef cases [] = {
		{ "bank_blocks",    case_bank_blocks },
		{ "rational_waits", case_rational_waits },
		{ "controls",       case_controls },
		{ "loop_restart",   case_loop_restart },
		{ "invalid",        case_invalid },
		{ "legacy",         case_legacy },
	};
	const int n = (int) (sizeof( cases ) / sizeof( cases [0] ));

	if ( argc == 1 )
	{
		for ( int i = 0; i < n; ++i )
		{
			failures = 0;
			cases [i].fn();
			if ( failures ) return 1;
			std::printf( "VGM_STREAM_CASE %s PASS\n", cases [i].name );
		}
		return 0;
	}
	if ( argc != 3 || std::strcmp( argv [1], "--case" ) != 0 )
	{
		std::fprintf( stderr, "usage: %s --case name\n", argv [0] );
		return 2;
	}
	for ( int i = 0; i < n; ++i )
	{
		if ( std::strcmp( argv [2], cases [i].name ) == 0 )
		{
			cases [i].fn();
			if ( failures ) return 1;
			std::printf( "VGM_STREAM_CASE %s PASS\n", cases [i].name );
			return 0;
		}
	}
	std::fprintf( stderr, "unknown case: %s\n", argv [2] );
	return 2;
}
